def utf8_prefix(data, max_bytes):
    result = b''
    count = 0
    i = 0
    length = len(data)
    while i < length:
        byte = data[i]
        if byte & 0x80 == 0:
            char_len = 1
        elif byte & 0xE0 == 0xC0:
            char_len = 2
        elif byte & 0xF0 == 0xE0:
            char_len = 3
        elif byte & 0xF8 == 0xF0:
            char_len = 4
        else:
            raise ValueError("Invalid UTF-8 start byte")
        if i + char_len > length:
            break
        for j in range(1, char_len):
            if data[i+j] & 0xC0 != 0x80:
                raise ValueError("Invalid UTF-8 continuation byte")
        if count + char_len > max_bytes:
            break
        result += data[i:i+char_len]
        count += char_len
        i += char_len
    return result
